#!/usr/bin/env python3
"""Read-only recovery of the 45 saved Open14B outputs and one timed-out attempt.

--run: snapshot -> local verified evidence copy -> offline validation/timing
       of the 45 saved sources -> descriptive partial report -> local copy.
No generation, model loading, runtime download, source mutation, or retry.
The remaining 854 slots stay NOT_ATTEMPTED; this cannot finish the 900-slot study.
Uses the original SHA-pinned validation/timing functions, not new numerical gates.
"""
from __future__ import annotations
import argparse,base64,contextlib,csv,gzip,hashlib,io,json,os,re,shlex,signal,socket,stat
import subprocess,sys,tarfile,tempfile,time,traceback,types,unittest,shutil
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
from unittest.mock import patch
PARENT_SHA='e747b2410ebcc1c67930143f88b734d07f0605052f17d800857b2d6f199911d0'
PARENT_GZ=''
raw=gzip.decompress(base64.b64decode(PARENT_GZ,validate=True))
if hashlib.sha256(raw).hexdigest()!=PARENT_SHA: raise RuntimeError('Embedded source hash mismatch')
P=types.ModuleType('_pinned_open14b_v2');P.__file__='<embedded-pinned-open14b-v2>'
sys.modules[P.__name__]=P
exec(compile(raw,P.__file__,'exec'),P.__dict__)
SOURCE=Path('/srv/research/cpucond-open14b-skylake-five-arm-v2')
ROOT=Path('/srv/research/cpucond-open14b-saved45-evaluation-v1')
SOURCE_UNIT='cpucond69-open14b-skylake-v2.service'
UNIT='cpucond69-open14b-saved45-eval-v1.service'
COMPLETE='OPEN14B_SAVED45_EVALUATION_COMPLETE_NOT_900'
CHECKPOINT_COMPLETE='OPEN14B_SAVED_EVIDENCE_CHECKPOINT'
TIMEOUT_ID='q27__heat-3d__MEDIUM__IR__W2__s0'
TIMEOUT_ERROR='Per-request wall limit reached; attempt retained'
MODEL=P.MODEL
read,save,jw,atomic,parse,canon,sha,hfile,need,checked,rel=P.read,P.save,P.jw,P.atomic,P.parse,P.canon,P.sha,P.hfile,P.need,P.checked,P.rel
Blocked=P.Blocked
now=P.now
LIVE={'active','activating','deactivating','reloading'}

def configure(root=None):
    if root is None:root=ROOT
    P.ROOT=root;P.UNIT=UNIT;P.COMPLETE=COMPLETE

@contextlib.contextmanager
def at_parent(root):
    old=P.ROOT;P.ROOT=root
    try:yield
    finally:P.ROOT=old

def state(unit):
    need(re.fullmatch(r'cpucond69-[A-Za-z0-9-]+\.service',unit),'Unexpected service name')
    r=subprocess.run(['systemctl','show',unit,'-p','LoadState','-p','ActiveState','-p','SubState','-p','Result','-p','ExecMainStatus','-p','MainPID'],capture_output=True,text=True,timeout=20)
    d=dict(l.split('=',1) for l in r.stdout.splitlines() if '=' in l)
    need(r.returncode==0 or (d.get('LoadState')=='not-found' and d.get('ActiveState')=='inactive'), 'Cannot query systemd state: '+r.stderr[:300])
    need(d.get('ActiveState') in LIVE|{'inactive','failed'},'Unrecognized systemd state')
    return d

def idle():
    need(state(SOURCE_UNIT).get('ActiveState') not in LIVE,'Original experiment still active; no changes made')
    for p in Path('/proc').iterdir():
        if not p.name.isdigit():continue
        try:name=(p/'comm').read_text().strip()
        except (FileNotFoundError,ProcessLookupError):continue
        need(name not in ('llama-server','ollama'),'Inference is active; not stopping an unrelated process')

def expected_record(row,code=None,error=None):
    cid=row['id']; ext='.c' if row['form']=='C' else '.ll'
    return dict(P.identity(cid),cohort=P.COHORT,prompt_condition_label=P.LABELS[row['condition']],
        generation_status='saved' if code is not None else 'invalid_generation',
        generation_errors=[] if error is None else [error],provider_result_type='native_llama_cpp',
        source_path='candidates/'+cid+ext if code is not None else None,
        source_sha256=sha(code.encode()) if code is not None else None,old_native_object=None)

def partial_stream(raw):
    tokens=0;characters=0;events=0
    for line in raw.splitlines():
        line=line.strip()
        if not line or line.startswith(b':'):continue
        need(line.startswith(b'data: '),'Malformed partial stream; evidence needs review')
        need(line[6:]!=b'[DONE]','Timeout stream contains DONE; needs reconciliation, not automatic retry')
        d=parse(line[6:]);need(isinstance(d,dict) and 'error' not in d,'Partial stream has protocol error')
        need(d.get('stop') is not True,'Timeout stream has a terminal response; requires reconciliation')
        text=d.get('content','');need(isinstance(text,str),'Nontext partial response')
        ts=d.get('tokens',[]);need(isinstance(ts,list) and all(type(x) is int for x in ts),'Malformed partial token IDs')
        tokens+=len(ts);characters+=len(text);events+=1
    need(events>0,'No streaming evidence for timeout')
    return dict(events=events,observed_token_ids=tokens,partial_characters=characters,
        used_as_candidate=False,terminal_response_present=False)

def audit_source(source=SOURCE):
    source=checked(source)
    need(hfile(source/'control/runner.py')==PARENT_SHA,'Original V2 runner changed')
    launch=parse(read(source/'control/start.json'))
    need(launch['runner_sha256']==PARENT_SHA and launch['model']==MODEL,'Source start metadata mismatch')
    progress=parse(read(source/'progress.json'));failure=parse(read(source/'failure.json'))
    need(progress.get('phase')=='BLOCKED' and progress.get('error')==TIMEOUT_ERROR,'Not the reported timeout failure')
    need(progress.get('generation_terminal')==progress.get('generation_saved')==45,'Expected exactly 45 saved outputs')
    need(progress.get('requests_total')==900 and progress.get('current_id')==TIMEOUT_ID,'Unexpected campaign/failure position')
    need(failure.get('error')=='Blocked: '+TIMEOUT_ERROR and failure.get('automatic_retry') is False,'Unexpected failure provenance')
    for n in ('validation','performance','analysis','generation-rows.json','completion-receipt.json'):
        need(not (source/n).exists(),'Later-stage artifacts already exist; refuse duplicate work: '+n)
    with at_parent(source):table=P.verify_inputs()
    rows=parse(read(source/'inputs/rows.json'))
    need(len(rows)==900 and {r['id'] for r in rows}==P.grid(),'Original planned grid is not exactly 900')
    need(rows[45]['id']==TIMEOUT_ID,'Fixed order does not match failed 46th slot')
    nr=parse(read(source/'native-input-receipt.json'))['rows']
    need(len(nr)==900 and [r['id'] for r in nr]==[r['id'] for r in rows],'Native-input receipt order differs')
    natives={r['id']:r for r in nr};native_docs={}
    for row in rows:
        cid=row['id'];blob=read(source/'native-inputs'/(cid+'.json'))
        need(sha(blob)==natives[cid]['sha256'],'Native-input bytes changed: '+cid)
        nd=parse(blob);need(nd['id']==cid and nd['native_input_tokens']==len(nd['tokens']),'Native-input count mismatch')
        need(nd['context_budget_ok']==P.token_budget(len(nd['tokens']),row['form']),'Native budget classification mismatch')
        native_docs[cid]=nd
    records_dir=source/'generation-records';attempts_dir=source/'generation'
    need({p.name for p in records_dir.iterdir()}=={r['id']+'.json' for r in rows[:45]},'Saved-record file set differs')
    need({p.name for p in attempts_dir.iterdir()}=={r['id'] for r in rows[:46]},'Attempt directory set differs')
    reconstructed=[];timings=[]
    for i,row in enumerate(rows[:46]):
        cid=row['id'];dest=attempts_dir/cid;nd=native_docs[cid]
        need(nd['context_budget_ok'] is True,'Attempt recorded for over-budget prompt')
        body=P.completion_body(nd['tokens'],row['form'])
        need(parse(read(dest/'request.json'))==body,'Saved request differs from frozen token input')
        intent=parse(read(dest/'intent.json'))
        need(intent.get('id')==cid and intent.get('attempt')==1 and intent.get('request_sha256')==sha(canon(body)),'Missing/changed intent')
        if i<45:
            need({p.name for p in dest.iterdir()}=={'request.json','intent.json','response.sse','response.txt','terminal.json'},'Unexpected saved-attempt files')
            text,final=P.parse_sse(read(dest/'response.sse',P.MAX_STREAM).splitlines())
            need(read(dest/'response.txt')==text.encode() and parse(read(dest/'terminal.json'))==final,'Response replay mismatch')
            code,error=P.classify(text,final,row['form'],len(nd['tokens']))
            need(code is not None and error is None,'Historical saved output fails original response checks')
            rr=expected_record(row,code)
            need(parse(read(records_dir/(cid+'.json')))==rr,'Historical generation record changed')
            need(read(source/'evaluation'/rr['source_path'])==code.encode(),'Saved candidate bytes changed')
            reconstructed.append(rr)
            timings.append(dict(id=cid,form=row['form'],input_tokens=len(nd['tokens']),
                generated_tokens=final.get('tokens_predicted',final.get('timings',{}).get('predicted_n')),
                native_timings=final.get('timings',{}),intent_utc=intent.get('utc')))
        else:
            need({p.name for p in dest.iterdir()}=={'request.json','intent.json','response.sse'},'Unexpected timeout artifacts')
            diagnostics=partial_stream(read(dest/'response.sse',P.MAX_STREAM))
            start=datetime.fromisoformat(intent['utc']);end=datetime.fromisoformat(failure['utc'])
            need(start.tzinfo is not None and end.tzinfo is not None and (end-start).total_seconds()>=21600,'Timeout chronology mismatch')
            reconstructed.append(expected_record(row,error='generation_wall_timeout_21600s'))
    candidate_set={p.relative_to(source/'evaluation').as_posix() for p in (source/'evaluation').rglob('*') if p.is_file()}
    need(candidate_set=={r['source_path'] for r in reconstructed if r['source_path']},'Candidate file set mismatch')
    coverage=[]
    for i,r in enumerate(rows):
        coverage.append(dict(P.identity(r['id']),generation_status='saved' if i<45 else 'timeout' if i==45 else 'not_attempted',
            attempt_count=1 if i<46 else 0))
    return dict(rows=reconstructed,coverage=coverage,timings=timings,timeout=diagnostics,
        source_root=str(source),planned_slots=900,attempted_slots=46,saved_outputs=45,
        generation_timeout_slots=1,not_attempted_slots=854,new_generation_calls=0,
        original_900_complete=False,source_completion=progress['phase'],source_failure_utc=failure['utc']),table

def checkpoint_paths(source,table):
    paths={'input-receipt.json':'input-receipt.json','inputs/snapshot-manifest.json':'inputs/snapshot-manifest.json',
        'native-input-receipt.json':'native-input-receipt.json'}
    paths.update({'inputs/'+n:'inputs/'+n for n in table})
    for name in ('native-inputs','generation','generation-records','acquisition'):
        for p in (source/name).rglob('*'):
            checked(p)
            if p.is_file():paths[p.relative_to(source).as_posix()]=p.relative_to(source).as_posix()
    for p in (source/'evaluation').rglob('*'):
        checked(p)
        if p.is_file():paths[p.relative_to(source).as_posix()]=p.relative_to(source).as_posix()
    for name in ('progress.json','failure.json','run.log','llama-server.log','control/start.json',
                 'control/launch.json','control/launch-submission.json','control/runner.py','preflight/identity-pipeline/receipt.json'):
        if (source/name).is_file():paths[name]='source-evidence/'+name
    return paths

def verify_snapshot():
    receipt=parse(read(ROOT/'checkpoint-receipt.json'))
    need(hfile(ROOT/'source-audit.json')==receipt['audit_sha256'],'Recovered audit changed after checkpoint')
    blob=read(ROOT/'source-snapshot.json');need(sha(blob)==receipt['manifest_sha256'],'Snapshot manifest changed')
    entries=parse(blob)
    for n,e in entries.items():
        need(hfile(ROOT/rel(n))==e['sha256'] and (ROOT/n).stat().st_size==e['bytes'],'Checkpoint content changed: '+n)
    return entries

def archive_checkpoint(entries):
    dest=ROOT/'source-checkpoint.tar.gz';part=dest.with_suffix('.gz.partial')
    table={n:e['sha256'] for n,e in entries.items()}
    table['source-snapshot.json']=hfile(ROOT/'source-snapshot.json')
    table['source-audit.json']=hfile(ROOT/'source-audit.json')
    seal=''.join(h+'  '+n+'\n' for n,h in sorted(table.items())).encode()
    with part.open('xb') as sink:
        with tarfile.open(fileobj=sink,mode='w:gz',compresslevel=1) as tf:
            for n in sorted(table):
                ti=tarfile.TarInfo(n);ti.size=(ROOT/n).stat().st_size;ti.mode=0o600
                with P.regular(ROOT/n) as fp:tf.addfile(ti,fp)
            ti=tarfile.TarInfo('SHA256SUMS');ti.size=len(seal);ti.mode=0o600;tf.addfile(ti,io.BytesIO(seal))
        sink.flush();os.fsync(sink.fileno())
    h=hfile(part);size=part.stat().st_size;P.verify_archive(part,h,size)
    os.rename(part,dest)
    return dict(path=str(dest),sha256=h,bytes=size)

def prepare_remote():
    P.host_basic();configure()
    with P.locks():
        idle()
        if ROOT.exists():
            need((ROOT/'checkpoint-receipt.json').is_file(),'Partial preparation retained; no overwrite')
            verify_snapshot();return
        audit,table=audit_source()
        with at_parent(SOURCE):
            _,c,e,_,_=P.modules();c.host_check(check_processes=False);e.no_other_jobs()
        paths=checkpoint_paths(SOURCE,table)
        need(len(paths)<30000,'Checkpoint too many files')
        total=sum((SOURCE/n).stat().st_size for n in paths)
        need(total<=2*P.GIB,'Checkpoint above 2GiB bound; no partial copy started')
        need(shutil.disk_usage('/root').free>=total*3+8*P.GIB,'Insufficient disk for checkpoint and evaluation')
        ROOT.mkdir(mode=0o700);manifest={}
        for origin,n in sorted(paths.items()):
            b=read(SOURCE/origin);save(ROOT/n,b);os.chmod(ROOT/n,0o444)
            manifest[n]=dict(source_path=str(SOURCE/origin),sha256=sha(b),bytes=len(b))
        for n,e in manifest.items():need(hfile(e['source_path'])==e['sha256'],'Source changed while copying')
        jw(ROOT/'source-snapshot.json',manifest);jw(ROOT/'source-audit.json',audit)
        ar=archive_checkpoint(manifest)
        jw(ROOT/'checkpoint-receipt.json',dict(completion=CHECKPOINT_COMPLETE,archive=ar,
            manifest_sha256=hfile(ROOT/'source-snapshot.json'),audit_sha256=hfile(ROOT/'source-audit.json'),utc=now(),model=MODEL,
            source_root=str(SOURCE),new_generation_calls=0,original_900_complete=False))
        verify_snapshot()
        print('SAVED45_AND_TIMEOUT_EVIDENCE_CHECKPOINT_READY; no generation or candidate execution',flush=True)


def systemd_command(runner):
    return ['systemd-run','--unit='+UNIT,'--property=Type=exec','--property=Restart=no',
        '--property=MemoryMax=24G','--property=MemorySwapMax=0','--property=TasksMax=256',
        '--property=RuntimeMaxSec=24h','--property=TimeoutStopSec=60','--property=KillMode=control-group',
        '--property=PrivateNetwork=yes','--property=UMask=0077','--property=LimitCORE=0',
        '--property=UnsetEnvironment=ANTHROPIC_API_KEY OPENAI_API_KEY CLAUDE_API_KEY HF_TOKEN HUGGING_FACE_HUB_TOKEN',
        '--property=StandardOutput=append:'+str(ROOT/'run.log'),'--property=StandardError=append:'+str(ROOT/'run.log'),
        '--setenv=CPUCOND_BATCH_UNIT='+UNIT,'--setenv=PYTHONDONTWRITEBYTECODE=1','--working-directory=/root','--',
        '/usr/bin/python3','-I','-S','-B','-u',str(runner),'--_worker']

def start_remote():
    P.host_basic();configure()
    with P.locks():
        verify_snapshot();idle()
        if (ROOT/'control/start.json').exists():
            need((ROOT/'completion-receipt.json').exists() or state(UNIT).get('ActiveState') in LIVE,
                'Existing evaluation retained; no automatic timing retry')
            return
        _,c,e,_,_=P.modules();c.host_check(check_processes=False);e.no_other_jobs()
        runner=ROOT/'control/runner.py';save(runner,read(__file__))
        jw(ROOT/'control/start.json',dict(runner_sha256=hfile(runner),unit=UNIT,
            boot_id=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),utc=now(),new_generation_calls=0))
        argv=systemd_command(runner);jw(ROOT/'control/launch.json',dict(argv=argv,utc=now()))
    r=subprocess.run(argv,capture_output=True,text=True,timeout=60,env=P.controls_env())
    atomic(ROOT/'control/submission.json',dict(returncode=r.returncode,stdout=r.stdout,stderr=r.stderr,utc=now()))
    need(r.returncode==0,'Launch not confirmed; inspect status, do not repeat candidate timing')
    print('SAVED45_OFFLINE_EVALUATION_STARTED; no LLM generation',flush=True)

def descriptive(core,outcomes,coverage):
    by={r['id']:r for r in outcomes};groups={}
    for row in outcomes:groups.setdefault((row['task'],row['size'],row['form']),{})[row['condition']]=row
    contrasts=[]
    for (task,size,form),rs in groups.items():
        for n,d in (('S1','P0'),('S2','P0'),('S1','W1'),('S2','W2')):
            a,b=rs.get(n),rs.get(d)
            if not a or not b or not(a['measurement_valid'] and b['measurement_valid']):continue
            need(a['baseline_object_sha256']==b['baseline_object_sha256'],'Matched baseline objects differ')
            contrasts.append(dict(task=task,size=size,form=form,contrast=n+'_over_'+d,
                numerator_id=a['id'],denominator_id=b['id'],speedup_ratio=a['speedup']/b['speedup']))
    full=[]
    for r in coverage:
        x=dict(r);x.update(evaluation_stage=by[r['id']]['stage'] if r['id'] in by else 'not_attempted',
            measurement_valid=by[r['id']]['measurement_valid'] if r['id'] in by else None,
            speedup=by[r['id']].get('speedup') if r['id'] in by else None)
        full.append(x)
    return dict(scope='Interrupted fixed-order prefix only; descriptive, not a complete 900-slot comparison.',
        attempted_slots=len(outcomes),not_attempted_slots=len(coverage)-len(outcomes),
        confidence_intervals_computed=False,whole_study_conclusions_supported=False,
        by_form_condition={f:{a:core.metric([r for r in outcomes if r['form']==f and r['condition']==a]) for a in P.ARMS} for f in P.FORMS}),contrasts,full

def run_worker():
    configure();P.cgroup_guard(private=True);idle()
    need(hfile(ROOT/'control/runner.py')==parse(read(ROOT/'control/start.json'))['runner_sha256'],'Recovery runner changed')
    with P.locks():
        verify_snapshot();P.verify_inputs();core,c,e,f,m=P.modules();c.host_check(check_processes=False);e.no_other_jobs()
        src=parse(read(ROOT/'source-audit.json'));rows=src['rows']
        need(len(rows)==46 and sum(r['generation_status']=='saved' for r in rows)==45,'Wrong recovered row count')
        core.TOTAL=46
        core.KERNELS=tuple(sorted({r['task'] for r in rows}))
        core.VCOMPLETE='OPEN14B_SAVED_PREFIX_VALIDATION_COMPLETE'
        core.PCOMPLETE='OPEN14B_SAVED_PREFIX_TIMING_COMPLETE'
        inp=ROOT/'evaluation'
        for n in parse(read(ROOT/'inputs/snapshot-manifest.json')):
            if n.startswith(('references/','package/','policy/')):
                save(inp/n,read(ROOT/'inputs'/n));os.chmod(inp/n,0o444)
        em={p.relative_to(inp).as_posix():hfile(p) for p in inp.rglob('*') if p.is_file()}
        jw(ROOT/'control/evaluation-inputs.json',em)
        boot=parse(read(ROOT/'control/start.json'))['boot_id']
        def check():
            need(Path('/proc/sys/kernel/random/boot_id').read_text().strip()==boot,'Server rebooted')
            c.controls()
        def check_inputs():
            for n,h in em.items():need(hfile(inp/rel(n))==h,'Evaluation input changed')
        P.update(phase='VALIDATING_SAVED45',planned_original_slots=900,evaluation_slots=46,new_generation_calls=0,
            generation_saved=45,generation_timeouts=1,not_attempted_slots=854,
            validation_slots_terminal=0,fullstate_passed=0,measurement_terminal=0,measurement_valid=0)
        v=c.import_validator(inp/'policy/validator-v1_2.py');clang,banner=c.compiler(v)
        previous=os.umask(0o022)
        try:vr=core.validation_loop(c,v,clang,rows,inp,ROOT/'validation',P.update,check)
        finally:os.umask(previous)
        vs=core.validation_summary(vr);jw(ROOT/'validation/result-index.json',vr);jw(ROOT/'validation/summary.json',vs)
        core.seal_phase(ROOT/'validation',core.VCOMPLETE);check_inputs()
        by={r['id']:r for r in vr};prows=[dict(r,correctness_passed=by[r['id']]['passed'],validation_status=by[r['id']]['status']) for r in rows]
        eligible=sum(r['correctness_passed'] for r in prows)
        P.update(phase='MEASURING_SAVED45',correctness_pass_eligible=eligible,measurement_pending=eligible)
        eng=m.pinned_engine(inp/'package');tc,tbanner=eng.clang_path()
        need(tbanner==banner and hfile(Path(tc).resolve())==P.CLANG_SHA,'Timing compiler differs')
        check();e.no_other_jobs();box=None;previous=os.umask(0o022)
        try:
            if eligible:box=eng.Sandbox(ROOT/'performance/sandbox');box.preflight()
            outcomes,bases=core.measurement_loop(m,eng,box,tc,prows,inp,ROOT/'performance',P.update,check)
        finally:
            os.umask(previous)
            if box:box.close()
        check_inputs();pm=core.metric(outcomes)
        need(pm['measurement_terminal']==eligible and pm['measurement_pending']==0,'Saved subset has pending timings')
        ps=dict(pm,completion=core.PCOMPLETE,baseline_policy=core.BASELINE,protocol=core.DEFAULTS,
            cpu=P.CPU,numa_node=P.NODE,timing_retries=0,compiler=banner,compiler_sha256=P.CLANG_SHA)
        jw(ROOT/'performance/summary.json',ps);save(ROOT/'performance/outcomes.jsonl',b''.join(canon(r) for r in outcomes))
        core.seal_phase(ROOT/'performance',core.PCOMPLETE)
        audit=core.audit_measured(m,f,eng,outcomes,ROOT/'performance')
        desc,contrasts,coverage=descriptive(core,outcomes,src['coverage'])
        jw(ROOT/'analysis/summary.json',dict(desc,measurement_audit=audit))
        save(ROOT/'analysis/outcomes.csv',core.table_csv(outcomes));save(ROOT/'analysis/coverage_900.csv',core.table_csv(coverage))
        save(ROOT/'analysis/matched_pairs_descriptive.csv',core.table_csv(contrasts))
        jw(ROOT/'analysis/generation-timings.json',src['timings'])
        summary=dict(completion=COMPLETE,model=MODEL,original_planned_slots=900,source_generation_attempts=46,
            source_saved_outputs=45,source_timeout_slots=1,not_attempted_slots=854,new_generation_calls=0,
            validation=vs,performance=ps,analysis=desc,whole_900_complete=False,
            formal_equivalence_proven=False,source_modified=False,source_root=str(SOURCE),
            timeouts_regenerated=False,preflight_results_counted_as_model_results=False,
            source_response_replay_verified=True,scientific_scope='Saved fixed-order prefix only.',completed_utc=now())
        jw(ROOT/'summary.json',summary);verify_snapshot();check_inputs();check()
        P.update(phase='ARCHIVING_SAVED_RESULTS')
        ar,sealdigest,n=core.archive_all(ROOT,P.update)
        # archive_all excludes live files; re-read gzip/footer and every member too.
        P.verify_archive(Path(ar['path']),ar['sha256'],ar['bytes'])
        jw(ROOT/'completion-receipt.json',dict(completion=COMPLETE,model=MODEL,
            summary_sha256=hfile(ROOT/'summary.json'),seal_sha256=sealdigest,archive=ar,
            sealed_files=n,whole_900_complete=False,utc=now()))
        P.update(phase='COMPLETE_SAVED45_NOT_900',whole_900_complete=False,measurement_pending=0)
        print(COMPLETE,flush=True)
        print(json.dumps({'validation_passed':vs['passed'],'valid_measurements':pm['measurement_valid'],
            'not_attempted':854,'timeout':1,'archive':ar},indent=2),flush=True)

def status_remote():
    P.host_basic();configure()
    if not ROOT.exists():return dict(state='NOT_PREPARED')
    d=dict(state='PREPARED',systemd=state(UNIT),whole_900_complete=False)
    for n in ('progress.json','failure.json','checkpoint-receipt.json','completion-receipt.json'):
        if (ROOT/n).is_file():d[n.removesuffix('.json')]=parse(read(ROOT/n))
    if d.get('completion-receipt'):
        r=d['completion-receipt'];need(r['completion']==COMPLETE,'Wrong partial completion')
        need(hfile(ROOT/'summary.json')==r['summary_sha256'] and hfile(ROOT/'SHA256SUMS')==r['seal_sha256'],'Completion metadata changed')
        d['state']='COMPLETE_SAVED45_NOT_900'
    elif d.get('failure'):d['state']='BLOCKED'
    elif d['systemd'].get('ActiveState') in LIVE:d['state']='RUNNING'
    elif (ROOT/'control/start.json').exists():d['state']='STOPPED_OR_BLOCKED'
    if d['state'] in ('BLOCKED','STOPPED_OR_BLOCKED') and (ROOT/'run.log').is_file():
        with P.regular(ROOT/'run.log') as f:f.seek(0,2);f.seek(max(0,f.tell()-6000));d['log_tail']=f.read().decode(errors='replace')
    return d

class Connection(P.SSH):
    def upload(self):
        b=read(__file__);digest=sha(b);self.script='/srv/research/cpucond-saved45-entry-'+digest[:16]+'.py'
        code="import os,sys,hashlib,socket; from pathlib import Path; assert os.geteuid()==0 and socket.gethostname().split('.')[0]=='cpucond-skylake-01'; p=Path(sys.argv[1]); b=sys.stdin.buffer.read(1024*1024); assert hashlib.sha256(b).hexdigest()==sys.argv[2] and not p.is_symlink(); os.umask(0o077); exists=p.exists(); assert not exists or p.read_bytes()==b; f=None if exists else p.open('xb'); f and (f.write(b),f.flush(),os.fsync(f.fileno()),f.close())"
        self.exec(['/usr/bin/python3','-I','-S','-B','-c',code,self.script,digest],input=b)
    def status(self):return parse(self.run('--_status',capture=True).stdout)

def collect_archive(conn,rec,label):
    ar=rec['archive'];path=ar['path']
    want=str(ROOT/'source-checkpoint.tar.gz') if label=='evidence' else str(ROOT)+'.tar.gz'
    need(path==want and P.HEX.fullmatch(ar['sha256']) and type(ar['bytes']) is int,'Unexpected remote archive')
    dest=checked(Path.home()/'workspace/cpu-conditioned-llm-optimization/runs/open14b-saved45-recovery-v1');dest.mkdir(parents=True,exist_ok=True)
    target=dest/Path(path).name;part=target.with_name(target.name+'.partial');rp=dest/(label+'-server-receipt.json')
    if rp.exists():need(parse(read(rp))==rec,'Existing local receipt differs')
    else:jw(rp,rec)
    if not target.exists():
        need(shutil.disk_usage(dest).free>ar['bytes']+P.GIB,'Not enough local disk')
        need(not part.is_symlink(),'Symlink partial refused')
        opts=[x for x in conn.opts if x!='-T']
        subprocess.run(['scp',*opts,P.SERVER+':'+path,str(part)],check=True)
        report=P.verify_archive(part,ar['sha256'],ar['bytes']);os.rename(part,target)
    else:report=P.verify_archive(target,ar['sha256'],ar['bytes'])
    atomic(dest/(label+'-local-receipt.json'),dict(report,path=str(target),utc=now(),whole_900_complete=False,server_receipt_sha256=sha(canon(rec))))
    print('OPEN14B_'+('SAVED_EVIDENCE' if label=='evidence' else 'SAVED45_RESULTS')+'_LOCAL_COPY_VERIFIED',flush=True)
    print('LOCAL_PATH='+str(target),flush=True)

def local(mode):
    need(socket.gethostname().split('.')[0]!=P.HOST,'User-facing modes run from local WSL')
    conn=Connection()
    try:
        conn.upload()
        if mode=='status':print(json.dumps(conn.status(),indent=2,ensure_ascii=False));return
        if mode=='run':conn.run('--_prepare')
        doc=conn.status()
        if doc.get('checkpoint-receipt'):collect_archive(conn,doc['checkpoint-receipt'],'evidence')
        if mode=='run':conn.run('--_start')
        last=None
        while True:
            doc=conn.status();pr=doc.get('progress',{})
            line=json.dumps(dict(state=doc['state'],phase=pr.get('phase'),new_generation_calls=0,
                attempted_slot_validation_terminal=pr.get('validation_slots_terminal'),
                measurement_terminal=pr.get('measurement_terminal'),measurement_pending=pr.get('measurement_pending'),
                original_900_complete=False),ensure_ascii=False)
            if line!=last:print(line,flush=True);last=line
            if doc['state']=='COMPLETE_SAVED45_NOT_900':collect_archive(conn,doc['completion-receipt'],'results');return
            if doc['state']!='RUNNING':
                print(json.dumps(doc,indent=2,ensure_ascii=False));raise Blocked('Not running. Evidence retained; no automatic retry.')
            time.sleep(30)
    except KeyboardInterrupt:print('Local monitor disconnected; owned offline evaluation continues. Reattach with --watch.')
    finally:conn.close()


