def main():
    sys.dont_write_bytecode=True
    parser=argparse.ArgumentParser(description=__doc__);g=parser.add_mutually_exclusive_group(required=True)
    for n in ('self-test','run','watch','status','_prepare','_start','_worker','_status'):
        g.add_argument('--'+n,action='store_true',help=argparse.SUPPRESS if n.startswith('_') else None)
    a=parser.parse_args()
    if a.self_test:self_test();return
    os.umask(0o077)
    if a._prepare:prepare_remote();return
    if a._start:start_remote();return
    if a._status:print(json.dumps(status_remote(),ensure_ascii=False));return
    if a._worker:
        def terminate(sig,frame):raise Blocked('Interrupted; all evidence retained, no automatic timing retry')
        signal.signal(signal.SIGTERM,terminate)
        try:run_worker()
        except BaseException as exc:
            atomic(ROOT/'failure.json',dict(error=type(exc).__name__+': '+str(exc),traceback=traceback.format_exc(),utc=now(),automatic_retry=False))
            configure();P.update(phase='BLOCKED',error=str(exc));raise
        return
    local('run' if a.run else 'watch' if a.watch else 'status')

if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:raise SystemExit(130)
    except Exception as exc:
        print('SAVED45_RECOVERY_BLOCKED: '+type(exc).__name__+': '+str(exc),file=sys.stderr,flush=True)
        print('No model generation; original V2 evidence and candidates are not changed.',file=sys.stderr)
        raise SystemExit(2)
